WITH remaining_keys AS (SELECT event_type FROM web_events EXCEPT ALL SELECT event_type FROM web_events WHERE page IN ('/search', '/product', '/checkout')), reconciled AS (SELECT s.* FROM web_events s INNER JOIN remaining_keys k ON s.event_type = k.event_type) SELECT CASE WHEN duration_sec >= 377 THEN 'LARGE' ELSE 'SMALL' END AS duration_sec_tier, AVG(duration_sec) FILTER (WHERE event_type = 'page_view') AS page_view_avg_duration_sec, ROUND(AVG(duration_sec), 2) AS avg_duration_sec, MAX(event_time) AS ended_at FROM reconciled GROUP BY CASE WHEN duration_sec >= 377 THEN 'LARGE' ELSE 'SMALL' END ORDER BY page_view_avg_duration_sec;
